// Spring Framework provides these annotations
@Service  // from spring-context
public class OrderService {

    @Autowired  // DI from Spring Framework
    private final OrderRepository orderRepository;

    @Transactional  // from spring-tx
    public Order createOrder(OrderRequest request) {
        var order = new Order(request.customerId(), request.items());
        return orderRepository.save(order);  // Spring Data JPA method
    }
}

// Spring Boot provides this auto-configuration
@SpringBootApplication  // Boot annotation that triggers auto-config
public class EcommerceApplication {
    public static void main(String[] args) {
        SpringApplication.run(EcommerceApplication.class, args);  // Boot starts everything
    }
}
// Boot sees spring-boot-starter-data-jpa and auto-configures:
// - HikariCP connection pool
// - JpaTransactionManager
// - EntityManagerFactory
// But the @Transactional logic? That's Spring Framework.

// Spring Boot brings it all together
@SpringBootApplication
public class EcommerceApplication {
    public static void main(String[] args) {
        SpringApplication.run(EcommerceApplication.class, args);
    }
}

// Spring MVC for REST endpoints
@RestController
@RequestMapping("/api/orders")
public class OrderController {
    private final OrderService orderService;

    @PostMapping
    public Order createOrder(@RequestBody OrderRequest request) {
        return orderService.createOrder(request);
    }
}

// Spring Data JPA for database
@Repository
public interface OrderRepository extends JpaRepository<Order, Long> {
    List<Order> findByCustomerId(Long customerId);
}

// Spring Security for authentication (with Boot starter)
@Configuration
public class SecurityConfig {
    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        return http.authorizeHttpRequests(auth -> auth.anyRequest().authenticated()).build();
    }
}
// All auto-configured by Boot when you add the respective starters

// Spring Boot auto-configures all of this with zero config
@SpringBootApplication
public class Application {
    public static void main(String[] args) {
        SpringApplication.run(Application.class, args);
    }
}

// Boot chooses:
// - Tomcat as the embedded server (from spring-boot-starter-web)
// - Jackson for JSON serialization (auto-configured when Jackson on classpath)
// - Logback for logging (default in spring-boot-starter-logging)
// - HikariCP for connection pooling (default in spring-boot-starter-data-jpa)

